#!/usr/bin/env python3
"""Compute CSX-113_Q1 standard-v1 hybrid numeric ground truth."""

from __future__ import annotations

import json
import re
from collections import defaultdict
from datetime import datetime, timezone
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-113_Q1"
EVENT_ID = "CSX-113"
EVENT_START = "2023-02-04"
EVENT_END = "2023-03-14"
LATE_WINDOW_DATES = ["2023-03-12", "2023-03-13", "2023-03-14"]
THRESHOLDS = {
    "late_3day_mm": 100.0,
    "late_share_pct": 25.0,
    "lag_hours": 48.0,
}


def package_dir() -> Path:
    return (
        Path(__file__).resolve().parents[3]
        / "event_packages"
        / "standard_event_packages"
        / "packages"
        / EVENT_ID
    )


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        text = " ".join(data.split())
        if text:
            self.parts.append(text)

    def text(self) -> str:
        return "\n".join(self.parts)


def html_text(path: Path) -> str:
    parser = TextExtractor()
    parser.feed(path.read_text(encoding="utf-8", errors="ignore"))
    return parser.text()


def extract_duration_days(text: str) -> float:
    patterns = [
        r"duration of\s+([0-9.]+)\s+days",
        r"at\s+([0-9.]+)\s+days",
        r"([0-9.]+)\s+days\s+at tropical storm status or higher",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            return float(match.group(1))
    raise ValueError("Could not extract duration in days")


def daily_precipitation(times: list[str], values: list[float]) -> dict[str, float]:
    daily: defaultdict[str, float] = defaultdict(float)
    for timestamp, value in zip(times, values):
        daily[timestamp[:10]] += float(value)
    return dict(sorted(daily.items()))


def parse_utc(value: str) -> datetime:
    return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)


def rolling_three_day_max(daily: dict[str, float]) -> dict[str, Any]:
    dates = sorted(daily)
    best_start = dates[0]
    best_total = -1.0
    for index in range(len(dates) - 2):
        window = dates[index : index + 3]
        total = sum(daily[date] for date in window)
        if total > best_total:
            best_start = window[0]
            best_total = total
    best_index = dates.index(best_start)
    return {
        "start": best_start,
        "end": dates[best_index + 2],
        "rain_mm": round(best_total, 1),
    }


def metric(value: float, unit: str, tolerance: float) -> dict[str, Any]:
    return {"value": value, "unit": unit, "tolerance": tolerance}


def rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Final ledger status",
                "points": 3,
                "description": "Reports pass with the requested four phases and numeric fields.",
                "partial_credit": "Award partial credit for the right status with one missing field or for a status that is clearly implied but not labeled.",
            },
            {
                "name": "Duration extraction",
                "points": 3,
                "description": "Reports 36.0 days within 0.2 days with units.",
                "partial_credit": "Award partial credit for a nearby duration that is not tied to the Freddy chronology.",
            },
            {
                "name": "Event and final-window precipitation",
                "points": 4,
                "description": "Aggregates hourly precipitation to 375.2 mm for the full event period and 111.7 mm for 2023-03-12 through 2023-03-14.",
                "partial_credit": "Award partial credit for a correct final-window sum with a missing or imprecise event total.",
            },
            {
                "name": "Share calculation",
                "points": 3,
                "description": "Computes 29.8% within 0.5 percentage points and compares it to the 25% threshold.",
                "partial_credit": "Award partial credit for using the right numerator but a wrong denominator.",
            },
            {
                "name": "Lag calculation",
                "points": 3,
                "description": "Computes 34.0 hours within 1.0 hour from 2023-03-12T00:00:00 to 2023-03-13T10:00:00 and compares it to the 48-hour threshold.",
                "partial_credit": "Award partial credit for the correct date order with an imprecise lag.",
            },
            {
                "name": "Threshold logic",
                "points": 2,
                "description": "Shows that all three checks pass and that one failed check would make the ledger fail.",
                "partial_credit": "Award partial credit for checking only two thresholds.",
            },
            {
                "name": "Concise answer format",
                "points": 2,
                "description": "Uses a compact JSON object or equivalent bullet list with units and one arithmetic sentence.",
                "partial_credit": "Award partial credit for correct values in a verbose or poorly structured answer.",
            },
        ],
    }


def main() -> None:
    root = package_dir()
    point = read_json(
        root,
        "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    )
    gdacs = read_json(root, "data/event_catalogs/event_catalogs_001_GDACS_tropical_cyclone_event_API.json")
    report = html_text(root / "data" / "event_reports" / "event_reports_001_Locked_package_evidence_report.html")

    duration_days = round(extract_duration_days(report), 1)

    hourly = point["hourly"]
    daily = daily_precipitation(hourly["time"], hourly["precipitation"])
    event_rain_mm = round(sum(daily[date] for date in sorted(daily) if EVENT_START <= date <= EVENT_END), 1)
    late_3day_mm = round(sum(daily[date] for date in LATE_WINDOW_DATES), 1)
    late_share_pct = round(100 * late_3day_mm / event_rain_mm, 1)
    wettest_late_day = max(LATE_WINDOW_DATES, key=lambda date: daily[date])

    flood_feature = next(
        feature
        for feature in gdacs["features"]
        if feature["properties"].get("eventtype") == "FL"
        and feature["properties"].get("country") == "Malawi"
    )
    flood_start = flood_feature["properties"]["fromdate"]
    lag_hours = round(
        (parse_utc(flood_start) - parse_utc(f"{wettest_late_day}T00:00:00")).total_seconds()
        / 3600,
        1,
    )

    checks = {
        "late_3day_mm": late_3day_mm >= THRESHOLDS["late_3day_mm"],
        "late_share_pct": late_share_pct >= THRESHOLDS["late_share_pct"],
        "lag_hours": lag_hours <= THRESHOLDS["lag_hours"],
    }
    status = "pass" if all(checks.values()) else "fail"
    phases = [
        {
            "phase": "long_duration_chronology",
            "time_window": "2023-02-04 through 2023-03-14 event chronology",
            "computed_values": {"duration_days": duration_days},
            "phase_role": "The full Freddy chronology is long-lived context rather than the deciding rainfall phase.",
        },
        {
            "phase": "full_period_rain_accumulation",
            "time_window": "2023-02-04 through 2023-03-14 local precipitation period",
            "computed_values": {"event_rain_mm": event_rain_mm},
            "phase_role": "The full-period rainfall total is the denominator for testing late-stage concentration.",
        },
        {
            "phase": "late_malawi_concentration",
            "time_window": "2023-03-12 through 2023-03-14",
            "computed_values": {"late_3day_mm": late_3day_mm, "late_share_pct": late_share_pct},
            "phase_role": "The final three days contain more than one quarter of the full-period local rainfall.",
        },
        {
            "phase": "flood_entry_lag_alignment",
            "time_window": "2023-03-12T00:00 to 2023-03-13T10:00",
            "computed_values": {"lag_hours": lag_hours},
            "phase_role": "The Malawi flood entry follows the wettest final-window day within the allowed 48-hour lag.",
        },
    ]
    interpretation = (
        "The Malawi episode is a distinct late-phase concentration because 111.7 mm falls in the final three days, "
        "representing 29.8% of local event rainfall, and the flood entry follows the wettest final-window day by 34.0 hours."
    )

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "freddy_late_phase_segmentation",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "phases": phases,
            "duration_days": duration_days,
            "event_rain_mm": event_rain_mm,
            "late_3day_mm": late_3day_mm,
            "late_share_pct": late_share_pct,
            "lag_hours": lag_hours,
            "status": status,
            "interpretation": interpretation,
        },
        "key_values": {
            "event_name": "Tropical Cyclone Freddy",
            "event_window": [EVENT_START, EVENT_END],
            "late_window": [LATE_WINDOW_DATES[0], LATE_WINDOW_DATES[-1]],
            "daily_late_mm": {date: round(daily[date], 1) for date in LATE_WINDOW_DATES},
            "wettest_late_day": wettest_late_day,
            "flood_start": flood_start,
            "max_3day_window": rolling_three_day_max(daily),
            "checks": checks,
            "metrics": {
                "duration_days": metric(duration_days, "days", 0.2),
                "event_rain_mm": metric(event_rain_mm, "mm", 0.5),
                "late_3day_mm": metric(late_3day_mm, "mm", 0.5),
                "late_share_pct": metric(late_share_pct, "percent", 0.5),
                "lag_hours": metric(lag_hours, "hours", 1.0),
            },
        },
        "rubric": rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
                "data/event_catalogs/event_catalogs_001_GDACS_tropical_cyclone_event_API.json",
                "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
            ],
        },
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
